```python
import re
from datetime import datetime

# Find the starting URL using DuckDuckGo search engine
search_query = "restaurants reservation platform near me pizza 6 guests"
results = web_search(search_query)
resy_url = None

for result in results:
    if "Resy" in result["title"]:
        resy_url = result["link"]
        break

if not resy_url:
    print("Couldn't find a suitable starting URL for Resy.")
    exit()

# Navigate to the discovered webpage using headless browser and retrieve visible text
browser = web_browser(resy_url)
page_text = browser.get_visible_text()

