            "type": "click",
            "selector": "#filter-guests input[value='6']"
        },
        {
            "type": "wait",
            "seconds": 3
        }
    ]
}

browser.execute_action_sequence(action_sequence)
filtered_page_text = browser.get_visible_text()

# Search within the filtered page text for restaurants with pizza and 6 guests
six_guest_restaurants = re.findall(r"(?s)(Restaurant|Eatery|Bistro|Pizzeria):\s+([^\n]+)", filtered_page_text, re.MULTILINE)

print("Page loaded: ", resy_url)
if six_guest_restaurants:
